def _resolve_json_payload(json_value: Any) -> dict:
    """
    Coerce the (possibly templated) ``json`` field into a plain ``dict``.

    When the ``json`` field resolves to a string (for example after Jinja rendering
    of a value pulled from XCom), it is parsed at execution time. The string is first
    tried as JSON and then, if that fails, as a Python literal (the representation
    Jinja produces when it renders a dict). The result is copied into a fresh ``dict``
    so callers can mutate it freely without touching the operator's template fields.
    """
    if isinstance(json_value, str):
        try:
            parsed = json_module.loads(json_value)
        except (json_module.JSONDecodeError, ValueError):
            try:
                parsed = ast.literal_eval(json_value)
            except (ValueError, SyntaxError):
                raise AirflowException("Databricks json payload string must be valid JSON")
    elif json_value is None:
        parsed = {}
    else:
        parsed = json_value

    if not isinstance(parsed, Mapping):
        raise AirflowException("Databricks json payload must resolve to a mapping")
    return dict(parsed)


